A VADODARA\' THEN \'SNITCH - FOCO - EVA\' WHEN a.store = \'LANDMARK GANDHI NAGAR\' THEN \'SNITCH - FOCO - GANDHI NAGAR\' WHEN a.store = \'MBH VARACHHA SURAT\' THEN \'SNITCH - FOCO - MBH\' WHEN a.store = \'PMC CITADEL\' THEN \'SNITCH - FOCO - PHEONIX CITADEL\' WHEN a.store = \'SHYAMAL\' THEN \'SNITCH - FOCO - SHYAMAL\' WHEN a.store = \'TRION VADODARA\' THEN \'SNITCH - FOCO - TRION\' WHEN a.store = \'VAISHALI NAGAR JAIPUR\' THEN \'SNITCH - FOCO - VAISHALI NAGAR\' WHEN a.store = \'VR MALL SURAT\' THEN \'SNITCH - FOCO - VR MALL\' WHEN a.store = \'YAGNIK\' THEN \'SNITCH - FOCO - YAGNIK\' WHEN a.store = \'Hubli\' THEN \'Mapping Pending\' WHEN a.store = \'Kothapet\' THEN \'Mapping Pending\' WHEN a.store = \'Lajpat Nagar\' THEN \'Mapping Pending\' WHEN a.store = \'Phoenix Palassio\' THEN \'Mapping Pending\' WHEN a.store = \'Rajahmundry\' THEN \'Mapping Pending\' ELSE \'Unknown Store\' END AS store_name_mapping FROM snitch_db1_wooqer a ) a LEFT JOIN ( SELECT EXTRACT(WEEK FROM TO_DATE(\"Date (dd/mm/yyyy)\", \'DD-MM-YYYY\')) AS week_number, COUNT(DISTINCT store) AS store_count FROM snitch_db1_wooqer GROUP BY EXTRACT(WEEK FROM TO_DATE(\"Date (dd/mm/yyyy)\", \'DD-MM-YYYY\')) ) b ON EXTRACT(WEEK FROM TO_DATE(a.\"Date (dd/mm/yyyy)\", \'DD-MM-YYYY\')) = b.week_number LEFT JOIN snitch_db.maplemonk.master_offine c ON a.store_name_mapping = c.\"FROM BRANCH NAME\" LEFT JOIN ( SELECT AM, COUNT(DISTINCT \"FROM BRANCH NAME\") AS AM_store_count FROM snitch_db.maplemonk.master_offine GROUP BY AM ) am_count ON c.AM = am_count.AM LEFT JOIN ( SELECT \"RM\", COUNT(DISTINCT \"FROM BRANCH NAME\") AS RM_store_count FROM snitch_db.maplemonk.master_offine GROUP BY \"RM\" ) rm_count ON c.RM = rm_count.RM;",
